def InvocationRequiresActiveFunction():
    for iid in inv_status:
        if inv_status[iid] == "IN_PROGRESS":
            fid = inv_func[iid]
            if fid in func_status:
                if func_status[fid] != "ACTIVE":
                    return False
    return True


# check: "sns" publishing requires an "ACTIVE" "sns" "topic" to be present

def PublishRequiresActiveTopic():
    for iid in inv_status:
        if inv_published[iid] == True:
            found = False
            for tid in topic_status:
                if topic_status[tid] == "ACTIVE":
                    found = True
            if found == False:
                return False
    return True
